    switch (status.toUpperCase()) {
      case 'ACCEPTED':
      case 'SELESAI':
      case 'CONFIRMED':
        return const Color(0xFF10B981);
      case 'REJECTED':
      case 'DITOLAK':
      case 'CANCELLED':
        return const Color(0xFFEF4444);
      case 'IN_PROGRESS':
      case 'DIPROSES':
        return const Color(0xFF3B82F6);
      default:
