  String _getStatusLabel(String status) {
    switch (status.toUpperCase()) {
      case 'ACCEPTED':
      case 'CONFIRMED':
        return 'Disetujui';
      case 'SELESAI':
        return 'Selesai';
      case 'REJECTED':
      case 'DITOLAK':
        return 'Ditolak';
      case 'IN_PROGRESS':
      case 'DIPROSES':
        return 'Sedang Diproses';
      default:
        return 'Menunggu Konfirmasi';
    }
  }

